  "atomic_questions": [
    "How many trained pilots does each fighter jet produce per year when it is allocated to pilot training?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific rate of pilot production per jet per year."
}

{
  "action": "question",
  "question_count": 1,
