  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do the fighter jets allocated to training in year 1 remain available to be allocated again in year 2, or are they consumed/retired after one year of training?"
  ],
  "rationale": "The response asks a single clarification question regarding the lifecycle/availability of assets across years, presented as a binary choice."
}

